with open(f'{base_dir}/app_ar.arb', 'r', encoding='utf-8') as f:
    ar_data = json.load(f)

placeholder_keys = {k: v for k, v in ar_data.items() if k.startswith('@')}

for locale, strings in translations.items():
    output = {"@@locale": locale}
    for key, value in strings.items():
        output[key] = value
        at_key = f'@{key}'
        if at_key in placeholder_keys:
            output[at_key] = placeholder_keys[at_key]
    
    filepath = f'{base_dir}/app_{locale}.arb'
    with open(filepath, 'w', encoding='utf-8') as f:
        json.dump(output, f, ensure_ascii=False, indent=2)
    print(f'✅ {locale}')

print('🎉 All done!')